-- Expand safe place keys without changing historical events or rollups.
alter table public.analytics_events drop constraint analytics_events_origin_check;
alter table public.analytics_events add constraint analytics_events_origin_check check (origin in ('unknown','other','airport-hahn','airport-frankfurt','airport-koeln-bonn','airport-duesseldorf','airport-luxemburg','cochem','klotten','valwig','valwigerberg','bruttig-fankel','ernst','beilstein','landkern','faid','treis-karden','ediger-eller','senheim','bremm','briedern','kaisersesch','ulmen','zell-mosel','koblenz','trier','burg-eltz','reichsburg') or (length(origin) <= 240 and origin ~ '^locality:[A-Z]{2}(-[A-Z0-9]{1,5})?:place[.][A-Za-z0-9_-]{1,80}:[[:alpha:]][[:alpha:] .’''()/-]{0,99}$'));
alter table public.analytics_events drop constraint analytics_events_destination_check;
alter table public.analytics_events add constraint analytics_events_destination_check check (destination in ('unknown','other','airport-hahn','airport-frankfurt','airport-koeln-bonn','airport-duesseldorf','airport-luxemburg','cochem','klotten','valwig','valwigerberg','bruttig-fankel','ernst','beilstein','landkern','faid','treis-karden','ediger-eller','senheim','bremm','briedern','kaisersesch','ulmen','zell-mosel','koblenz','trier','burg-eltz','reichsburg') or (length(destination) <= 240 and destination ~ '^locality:[A-Z]{2}(-[A-Z0-9]{1,5})?:place[.][A-Za-z0-9_-]{1,80}:[[:alpha:]][[:alpha:] .’''()/-]{0,99}$'));
